SELECT Федеральные_округа.name AS Fed_okr, [Станции_для_сводной(архив)].nameoes, Имена_областей.NAME AS oblast, имена_ГК.name AS Gen_komp, [Станции_для_сводной(архив)].NAME AS Stancia, [Станции_для_сводной(архив)].numb1120, [Станции_для_сводной(архив)].Year, [Станции_для_сводной(архив)].NUST, IIf([W]>0,[W],0) AS W_en, IIf([Qotp]>0,[Qotp],0) AS Teplo, ([gaz_est]+[gaz_isk])*1000 AS GAZ_All, [gaz_est]*1000 AS GAZ_ESTEST, IIf([GAZ_ekol]>0,[GAZ_ekol],0) AS GAZ_ek, [GAZ_ESTEST]-[GAZ_ek] AS d_gaz, [Выбросы ПГ].CO2_gaz, IIf([CO2_gaz]>0,[CO2_gaz]/[GAZ_ek],0) AS K_gaz_ek, IIf([MAZUT]>0,[MAZUT]*1000,0) AS MAZUT_6tp, IIf([MAZUT_ekol]>0,[MAZUT_ekol],0) AS MAZUT_ek, [MAZUT_6tp]-[MAZUT_ek] AS d_mazut, [Выбросы ПГ].CO2_mazut, ([ugol_6tp]+[torf_6tp]+[proch_tverd])*1000 AS TvTopl_6tp, IIf([UGOL_ekol]>0,[UGOL_ekol],0) AS TvTopl_ek, [TvTopl_6tp]-[TvTopl_ek] AS d_tv, [Выбросы ПГ].CO2_ugol, [Выбросы ПГ].CO2, [Выбросы ПГ].SF6, IIf(([B]-[GAZ_ALL]-[MAZUT_6tp]-[TvTopl_6tp])>0,([B]-[GAZ_ALL]-[MAZUT_6tp]-[TvTopl_6tp])*1000,0) AS PROCH_6tp, IIf([CO2_mazut]>0,[CO2_mazut]/[MAZUT_ek],0) AS K_mazut_ek, IIf([CO2_ugol]>0,[CO2_ugol]/[TvTopl_ek],0) AS K_ugol_ek, IIf([CO2]>0,[CO2]/([GAZ_ek]+[MAZUT_ek]+[TvTopl_ek])*1000,0) AS UD_CO2_ek, IIf([W_en]>0 Or [Teplo]>0,[CO2]/([W_en]+[Teplo]*1000/859.8),0) AS UD_CO2_ener, [Станции_для_сводной(архив)].OBOR, IIf([CO2]>0,[CO2]-[CO2_gaz]-[CO2_mazut]-[CO2_ugol],0) AS проверка, [Станции_для_сводной(архив)].group, IIf([Ведомство]=1,"МинЭн","Пром.предпр.") AS BLST
FROM ((([Станции_для_сводной(архив)] LEFT JOIN [Выбросы ПГ] ON ([Станции_для_сводной(архив)].YEAR = [Выбросы ПГ].year) AND ([Станции_для_сводной(архив)].NUMB1120 = [Выбросы ПГ].numb1120)) INNER JOIN (Имена_станций INNER JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) ON [Станции_для_сводной(архив)].numb1120 = Имена_станций.NUMB) INNER JOIN Федеральные_округа ON [Станции_для_сводной(архив)].FO = Федеральные_округа.fo) INNER JOIN Имена_областей ON [Станции_для_сводной(архив)].obl = Имена_областей.OBL
WHERE ((([Станции_для_сводной(архив)].group)=0 Or ([Станции_для_сводной(архив)].group) Is Null) AND (([Станции_для_сводной(архив)].Year)>2016))
ORDER BY Имена_станций.ordnumb, [Станции_для_сводной(архив)].Year, имена_ГК.name;
